// ---------- Minimal Supabase REST client (no external libraries) ----------
async function sbRequest(path, { method = "GET", body, accessToken, headers = {} } = {}) {
  const res = await fetch(`${SUPABASE_URL}${path}`, {
    method,
    headers: {
      apikey: SUPABASE_ANON_KEY,
      Authorization: `Bearer ${accessToken || SUPABASE_ANON_KEY}`,
      "Content-Type": "application/json",
      ...headers,
    },
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let data = null;
  try { data = text ? JSON.parse(text) : null; } catch (e) { data = text; }
  if (!res.ok) {
    const msg = (data && (data.msg || data.message || data.error_description || data.error)) || res.statusText;
    throw new Error(msg);
  }
  return data;
}

const auth = {
  signUp: (email, password) => sbRequest("/auth/v1/signup", { method: "POST", body: { email, password } }),
  signIn: (email, password) => sbRequest("/auth/v1/token?grant_type=password", { method: "POST", body: { email, password } }),
  signOut: (accessToken) => sbRequest("/auth/v1/logout", { method: "POST", accessToken }).catch(() => {}),
  updateUser: (accessToken, updates) => sbRequest("/auth/v1/user", { method: "PUT", body: updates, accessToken }),
  refresh: (refreshToken) => sbRequest("/auth/v1/token?grant_type=refresh_token", { method: "POST", body: { refresh_token: refreshToken } }),
};

const SESSION_KEY = "origin_crm_session";
const saveSession = (session) => {
  try { localStorage.setItem(SESSION_KEY, JSON.stringify(session)); } catch (e) {}
};
const loadSession = () => {
  try {
    const raw = localStorage.getItem(SESSION_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch (e) { return null; }
};
const clearSession = () => {
  try { localStorage.removeItem(SESSION_KEY); } catch (e) {}
};

const db = {
  select: (table, query = "", accessToken) => sbRequest(`/rest/v1/${table}?select=*${query}`, { accessToken }),
  insert: (table, row, accessToken) =>
    sbRequest(`/rest/v1/${table}`, { method: "POST", body: row, accessToken, headers: { Prefer: "return=representation" } }),
  update: (table, id, changes, accessToken) =>
    sbRequest(`/rest/v1/${table}?id=eq.${id}`, { method: "PATCH", body: changes, accessToken, headers: { Prefer: "return=representation" } }),
  remove: (table, id, accessToken) => sbRequest(`/rest/v1/${table}?id=eq.${id}`, { method: "DELETE", accessToken }),
  removeWhere: (table, filterQuery, accessToken) => sbRequest(`/rest/v1/${table}?${filterQuery}`, { method: "DELETE", accessToken }),
  upsert: (table, rows, onConflict, accessToken) =>
    sbRequest(`/rest/v1/${table}?on_conflict=${onConflict}`, { method: "POST", body: rows, accessToken, headers: { Prefer: "resolution=merge-duplicates,return=representation" } }),
  rpc: (fn, args, accessToken) => sbRequest(`/rest/v1/rpc/${fn}`, { method: "POST", body: args, accessToken }),
  // Reads every row (Supabase returns max 1000 per request)
  selectAll: async (table, query = "", accessToken) => {
    const out = [];
    for (let offset = 0; ; offset += 1000) {
      const rows = await sbRequest(`/rest/v1/${table}?select=*${query}&limit=1000&offset=${offset}`, { accessToken });
      out.push(...(rows || []));
      if (!rows || rows.length < 1000) break;
    }
    return out;
  },
};

const storage = {
  upload: async (bucket, path, file, accessToken) => {
    const res = await fetch(`${SUPABASE_URL}/storage/v1/object/${bucket}/${path}`, {
      method: "POST",
      headers: {
        apikey: SUPABASE_ANON_KEY,
        Authorization: `Bearer ${accessToken || SUPABASE_ANON_KEY}`,
        "Content-Type": file.type || "application/octet-stream",
      },
      body: file,
    });
    if (!res.ok) {
      const t = await res.text();
      throw new Error(t || "Upload failed");
    }
    return `${SUPABASE_URL}/storage/v1/object/public/${bucket}/${path}`;
  },
};

