// ---------- Org tree helpers ----------
function getSubtreeIds(users, rootId) {
  const result = [rootId];
  const children = users.filter((u) => u.managerId === rootId);
  children.forEach((c) => result.push(...getSubtreeIds(users, c.id)));
  return result;
}

// ---------- Small UI helpers ----------
function Field({ label, children, required }) {
  return (
    <label style={{ display: "flex", flexDirection: "column", gap: 6, fontSize: 13, color: COLORS.text }}>
      <span style={{ fontWeight: 500 }}>
        {label}{required && <span style={{ color: COLORS.danger }}> *</span>}
      </span>
      {children}
    </label>
  );
}

const inputStyle = {
  border: `1px solid ${COLORS.border}`,
  borderRadius: 6,
  padding: "10px 11px",
  fontSize: 16,
  background: "#fff",
  color: COLORS.text,
  outline: "none",
  fontFamily: "inherit",
  width: "100%",
};

function Select({ value, onChange, options, placeholder }) {
  return (
    <select value={value} onChange={(e) => onChange(e.target.value)} style={{ ...inputStyle, appearance: "none" }}>
      <option value="">{placeholder || "Select..."}</option>
      {options.map((o) => (
        <option key={o} value={o}>{o}</option>
      ))}
    </select>
  );
}

function RangeField({ label, minValue, maxValue, onMinChange, onMaxChange }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
      <span style={{ fontSize: 12, color: COLORS.textMuted }}>{label}</span>
      <div style={{ display: "flex", gap: 6 }}>
        <input style={{ ...inputStyle, width: 80 }} type="number" placeholder="Min" value={minValue} onChange={(e) => onMinChange(e.target.value)} />
        <input style={{ ...inputStyle, width: 80 }} type="number" placeholder="Max" value={maxValue} onChange={(e) => onMaxChange(e.target.value)} />
      </div>
    </div>
  );
}

function Badge({ children, tone = "neutral" }) {
  const tones = {
    neutral: { bg: COLORS.creamDark, color: COLORS.text },
    hold: { bg: "#F3E3DC", color: COLORS.danger },
    active: { bg: "#E1EAE4", color: COLORS.success },
    pending: { bg: "#F3E3DC", color: COLORS.danger },
  };
  const t = tones[tone] || tones.neutral;
  return (
    <span style={{ background: t.bg, color: t.color, fontSize: 11, fontWeight: 600, padding: "3px 9px", borderRadius: 20, letterSpacing: 0.2 }}>
      {children}
    </span>
  );
}

function money(n) {
  if (!n && n !== 0) return "—";
  return Number(n).toLocaleString("en-US") + " EGP";
}
function formatDate(iso) {
  if (!iso) return "—";
  const d = new Date(iso);
  return d.toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" });
}

// One-tap Call + WhatsApp buttons next to any phone number
function ContactButtons({ phone, size = 12 }) {
  if (!phone) return null;
  const digits = phone.replace(/[^0-9+]/g, "");
  return (
    <span style={{ display: "inline-flex", gap: 6, marginLeft: 4 }} onClick={(e) => e.stopPropagation()}>
      <a href={`tel:${digits}`} style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", width: 22, height: 22, borderRadius: "50%", background: COLORS.navy, color: "#fff", textDecoration: "none" }} title="Call">
        <Phone size={size - 1} />
      </a>
      <a href={`https://wa.me/${digits.replace(/^\+/, "")}`} target="_blank" rel="noreferrer" style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", width: 22, height: 22, borderRadius: "50%", background: "#25D366", color: "#fff", textDecoration: "none" }} title="WhatsApp">
        <MessageSquare size={size - 1} />
      </a>
    </span>
  );
}

