function EditProfile({ profile, currentEmail, onSave, onUploadAvatar, onUpdateEmail }) {
  const [name, setName] = useState(profile.name);
  const [phone, setPhone] = useState(profile.phone);
  const [email, setEmail] = useState(currentEmail);
  const [avatarPreview, setAvatarPreview] = useState(profile.avatarUrl || "");
  const [avatarFile, setAvatarFile] = useState(null);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);
  const [saving, setSaving] = useState(false);

  const pickAvatar = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setAvatarFile(file);
    setAvatarPreview(URL.createObjectURL(file));
  };

  const save = async () => {
    if (!name.trim()) {
      setError("Enter your name.");
      return;
    }
    setError(""); setSuccess(false); setSaving(true);
    try {
      let avatarUrl = profile.avatarUrl || "";
      if (avatarFile) avatarUrl = await onUploadAvatar(avatarFile);
      await onSave({ name: name.trim(), phone: phone.trim(), avatarUrl });
      if (email.trim() && email.trim() !== currentEmail) {
        await onUpdateEmail(email.trim());
      }
      setSuccess(true);
      setAvatarFile(null);
    } catch (err) {
      setError(err.message || "Could not save changes.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div style={{ maxWidth: 380, background: "#fff", border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: 20 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 16 }}>
        <div style={{ width: 64, height: 64, borderRadius: "50%", overflow: "hidden", background: COLORS.creamDark, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          {avatarPreview ? (
            <img src={avatarPreview} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          ) : (
            <UserRound size={28} color={COLORS.textMuted} />
          )}
        </div>
        <label style={{ fontSize: 12, color: COLORS.navy, cursor: "pointer", border: `1px solid ${COLORS.border}`, padding: "7px 12px", borderRadius: 8 }}>
          Change photo
          <input type="file" accept="image/*" hidden onChange={pickAvatar} />
        </label>
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        <Field label="Full name" required>
          <input style={inputStyle} value={name} onChange={(e) => setName(e.target.value)} />
        </Field>
        <Field label="Phone">
          <input style={inputStyle} value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="01xxxxxxxxx" />
        </Field>
        <Field label="Email">
          <input style={inputStyle} type="email" value={email} onChange={(e) => setEmail(e.target.value)} />
        </Field>
      </div>
      {error && <div style={{ color: COLORS.danger, fontSize: 13, marginTop: 12 }}>{error}</div>}
      {success && <div style={{ color: COLORS.success, fontSize: 13, marginTop: 12 }}>Saved.</div>}
      <button
        disabled={saving}
        onClick={save}
        style={{ marginTop: 16, background: COLORS.navy, color: "#fff", border: "none", padding: "9px 18px", borderRadius: 8, fontSize: 13, fontWeight: 500, cursor: saving ? "default" : "pointer", opacity: saving ? 0.7 : 1 }}
      >
        {saving ? "Saving…" : "Save changes"}
      </button>
    </div>
  );
}

function ManageUsers({ users, onApprove, onRemove, onEdit }) {
  const [editingId, setEditingId] = useState(null);
  const [editRole, setEditRole] = useState("");
  const [editManagerId, setEditManagerId] = useState("");
  const [error, setError] = useState("");

  const pending = users.filter((u) => u.role === "pending");
  const active = users.filter((u) => u.role !== "pending" && u.role !== "admin");
  const possibleManagers = users.filter((u) => u.role !== "admin" && u.role !== "pending" && u.role !== "sales_agent");

  const roleIdForLabel = (label) => ROLES.find((r) => r.label === label)?.id;
  const managerName = (id) => users.find((u) => u.id === id)?.name || "—";

  const startEdit = (u) => {
    setEditingId(u.id);
    setEditRole(u.role === "pending" ? "" : ROLE_LABEL[u.role]);
    setEditManagerId(u.managerId || "");
    setError("");
  };

  const save = (u, isApproval) => {
    const newRoleId = roleIdForLabel(editRole);
    if (!newRoleId) { setError("Choose a role."); return; }
    if (newRoleId !== "ceo" && !editManagerId) { setError("Choose who this person reports to."); return; }
    setError("");
    const changes = { role: newRoleId, managerId: newRoleId === "ceo" ? null : Number(editManagerId) || editManagerId };
    if (isApproval) onApprove(u.id, changes);
    else onEdit(u.id, changes);
    setEditingId(null);
  };

  const EditRow = ({ u, isApproval }) => (
    <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(140px, 1fr))", gap: 8, alignItems: "end" }}>
      <Field label="Role">
        <Select value={editRole} onChange={setEditRole} options={ROLES.filter((r) => r.id !== "admin" && r.id !== "pending").map((r) => r.label)} />
      </Field>
      <Field label="Reports to">
        <select value={editManagerId} onChange={(e) => setEditManagerId(e.target.value)} style={{ ...inputStyle, appearance: "none" }} disabled={editRole === "CEO"}>
          <option value="">{editRole === "CEO" ? "None" : "Select..."}</option>
          {possibleManagers.filter((m) => m.id !== u.id).map((m) => (
            <option key={m.id} value={m.id}>{m.name} ({ROLE_LABEL[m.role]})</option>
          ))}
        </select>
      </Field>
      <button onClick={() => save(u, isApproval)} style={{ border: "none", background: COLORS.navy, color: "#fff", padding: "9px 12px", borderRadius: 8, cursor: "pointer", fontSize: 12 }}>
        {isApproval ? "Approve" : "Save"}
      </button>
      <button onClick={() => setEditingId(null)} style={{ border: `1px solid ${COLORS.border}`, background: "#fff", padding: "9px 12px", borderRadius: 8, cursor: "pointer", fontSize: 12 }}>
        Cancel
      </button>
    </div>
  );

  return (
    <div>
      {pending.length > 0 && (
        <div style={{ marginBottom: 24 }}>
          <div style={{ fontWeight: 500, fontSize: 14, color: COLORS.navy, marginBottom: 10 }}>Pending approval ({pending.length})</div>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {pending.map((u) => (
              <div key={u.id} style={{ background: "#fff", border: `1px solid ${COLORS.gold}`, borderRadius: 8, padding: "10px 14px" }}>
                {editingId === u.id ? (
                  <EditRow u={u} isApproval={true} />
                ) : (
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                    <div>
                      <span style={{ fontWeight: 500, fontSize: 13, color: COLORS.text }}>{u.name}</span>
                      <span style={{ fontSize: 12, color: COLORS.textMuted, marginLeft: 8 }}>{u.phone}</span>
                    </div>
                    <button onClick={() => startEdit(u)} style={{ border: "none", background: COLORS.gold, color: "#fff", padding: "6px 14px", borderRadius: 8, cursor: "pointer", fontSize: 12, fontWeight: 500 }}>
                      Set role
                    </button>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {error && <div style={{ color: COLORS.danger, fontSize: 13, marginBottom: 14 }}>{error}</div>}

      <div style={{ fontWeight: 500, fontSize: 14, color: COLORS.navy, marginBottom: 10 }}>Company directory</div>
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {active.map((u) => (
          <div key={u.id} style={{ background: "#fff", border: `1px solid ${COLORS.border}`, borderRadius: 8, padding: "10px 14px" }}>
            {editingId === u.id ? (
              <EditRow u={u} isApproval={false} />
            ) : (
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                <div>
                  <span style={{ fontWeight: 500, fontSize: 13, color: COLORS.text }}>{u.name}</span>
                  <span style={{ fontSize: 12, color: COLORS.textMuted, marginLeft: 8 }}>{ROLE_LABEL[u.role]}</span>
                  {u.managerId && <span style={{ fontSize: 12, color: COLORS.textMuted, marginLeft: 8 }}>reports to {managerName(u.managerId)}</span>}
                </div>
                <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
                  <button onClick={() => startEdit(u)} style={{ border: "none", background: "none", color: COLORS.navy, cursor: "pointer", fontSize: 12 }}>Edit</button>
                  <button onClick={() => onRemove(u.id)} style={{ border: "none", background: "none", color: COLORS.danger, cursor: "pointer", display: "flex", alignItems: "center" }} aria-label="Remove user">
                    <Trash2 size={15} />
                  </button>
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

