      <div style={{ fontSize: 19, fontWeight: 800, color, fontVariantNumeric: "tabular-nums" }}>{value}</div>
      {sub && <div style={{ fontSize: 11.5, color: COLORS.textMuted, marginTop: 3 }}>{sub}</div>}
