function NamedListEditor({ title, items, onAdd, onToggleArchive, extra }) {
  const [text, setText] = useState("");
  const { busy, error, run } = useAction();
  return (
    <div style={finCard}>
      <div style={{ fontWeight: 600, fontSize: 14, color: COLORS.navy, marginBottom: 8 }}>{title}</div>
      <div style={{ display: "flex", flexDirection: "column", gap: 6, marginBottom: 10 }}>
        {items.map((it) => (
          <div key={it.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", fontSize: 13, opacity: it.archived ? 0.5 : 1 }}>
            <span>{it.name}{extra ? extra(it) : ""}{it.archived ? " (hidden)" : ""}</span>
            <button style={{ ...btnGhost, padding: "3px 8px", fontSize: 11 }} disabled={busy} onClick={() => run(() => onToggleArchive(it))}>{it.archived ? "Show" : "Hide"}</button>
          </div>
        ))}
      </div>
      <div style={{ display: "flex", gap: 6 }}>
        <input style={inputStyle} placeholder="New name" value={text} onChange={(e) => setText(e.target.value)} />
        <button style={btnPrimary} disabled={busy || !text.trim()} onClick={() => run(async () => { await onAdd(text.trim()); setText(""); })}>Add</button>
      </div>
      <FinError text={error} />
    </div>
  );
}

function CharitySettings({ ctx }) {
  const { fin, act } = ctx;
  const [pct, setPct] = useState(String(fin.settings?.charity_pct ?? 1));
  const [accountId, setAccountId] = useState(fin.settings?.charity_account_id || "");
  const { busy, error, run } = useAction();
  const [saved, setSaved] = useState(false);
  return (
    <div style={finCard}>
      <div style={{ fontWeight: 600, fontSize: 14, color: COLORS.navy, marginBottom: 4 }}>Floos Rabna</div>
      <div style={{ fontSize: 12, color: COLORS.textMuted, marginBottom: 10 }}>
        This % of every collected commission moves automatically into the chosen account. It comes out of the company's share only — the team's commissions don't change and they don't see it.
      </div>
      <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 8 }}>
        <input type="number" step="0.1" min="0" style={{ ...inputStyle, width: 90, padding: "6px 8px" }} value={pct} onChange={(e) => setPct(e.target.value)} />
        <span style={{ fontSize: 12, color: COLORS.textMuted }}>% into</span>
        <select value={accountId} onChange={(e) => setAccountId(e.target.value)} style={{ ...inputStyle, appearance: "none", padding: "6px 8px" }}>
          <option value="">— Off —</option>
          {fin.accounts.filter((a) => !a.archived || a.id === accountId).map((a) => <option key={a.id} value={a.id}>{a.name}</option>)}
        </select>
      </div>
      <div style={{ fontSize: 11.5, color: COLORS.textMuted, marginBottom: 8 }}>Changes apply to new collections only.</div>
      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
        <button style={btnPrimary} disabled={busy} onClick={() => run(async () => {
          setSaved(false);
          if (num(pct) < 0 || num(pct) > 100) throw new Error("Enter a % between 0 and 100.");
          await act((t) => db.update("finance_settings", 1, { charity_pct: num(pct), charity_account_id: accountId || null, updated_at: new Date().toISOString() }, t));
          setSaved(true);
        })}>Save</button>
        {saved && <span style={{ color: COLORS.success, fontSize: 12.5 }}>Saved ✓</span>}
      </div>
      <FinError text={error} />
    </div>
  );
}

function FinSettings({ ctx }) {
  const { fin, act, thresholds, addCategory } = ctx;
  const [tiers, setTiers] = useState(thresholds.map(String));
  const tierAction = useAction();
  const recAction = useAction();
  const [rec, setRec] = useState({ name: "", categoryId: "", amount: "" });
  const catName = (id) => fin.categories.find((c) => c.id === id)?.name || "—";
  return (
    <>
      <FinTitle>Finance settings</FinTitle>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))", gap: 14 }}>
        <div style={finCard}>
          <div style={{ fontWeight: 600, fontSize: 14, color: COLORS.navy, marginBottom: 4 }}>Commission tiers</div>
          <div style={{ fontSize: 12, color: COLORS.textMuted, marginBottom: 10 }}>% of quarterly target where each higher rate starts. Rates per person are set in the Team tab.</div>
          {tiers.map((t, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
              <span style={{ fontSize: 13, width: 60 }}>{i === 0 ? "Base" : `Tier ${i}`}</span>
              <input type="number" disabled={i === 0} style={{ ...inputStyle, width: 100, padding: "6px 8px" }} value={t}
                onChange={(e) => setTiers((l) => l.map((x, j) => (j === i ? e.target.value : x)))} />
              <span style={{ fontSize: 12, color: COLORS.textMuted }}>% of target</span>
              {i > 0 && i === tiers.length - 1 && <button style={{ border: "none", background: "none", color: COLORS.danger, cursor: "pointer" }} onClick={() => setTiers((l) => l.slice(0, -1))}><X size={14} /></button>}
            </div>
          ))}
          <div style={{ display: "flex", gap: 6, marginTop: 8 }}>
            <button style={btnGhost} onClick={() => setTiers((l) => [...l, String(num(l[l.length - 1]) + 30)])}>+ Add tier</button>
            <button style={btnPrimary} disabled={tierAction.busy} onClick={() => tierAction.run(async () => {
              const vals = tiers.map(num);
              if (vals.some((v, i) => i > 0 && v <= vals[i - 1])) throw new Error("Each tier must be higher than the one before.");
              await act((t) => db.update("finance_settings", 1, { tier_thresholds: vals, updated_at: new Date().toISOString() }, t));
            })}>Save tiers</button>
          </div>
          <FinError text={tierAction.error} />
        </div>

        <CharitySettings ctx={ctx} />

        <NamedListEditor title="Accounts (treasuries)" items={fin.accounts}
          onAdd={(name) => act((t) => db.insert("finance_accounts", { name }, t))}
          onToggleArchive={(it) => act((t) => db.update("finance_accounts", it.id, { archived: !it.archived }, t))} />

        <NamedListEditor title="Expense categories" items={fin.categories}
          onAdd={(name) => addCategory(name)}
          onToggleArchive={(it) => act((t) => db.update("expense_categories", it.id, { archived: !it.archived }, t))} />

        <div style={finCard}>
          <div style={{ fontWeight: 600, fontSize: 14, color: COLORS.navy, marginBottom: 4 }}>Fixed monthly items</div>
          <div style={{ fontSize: 12, color: COLORS.textMuted, marginBottom: 10 }}>Rent, internet, bills… They show up every month in Expenses with a "Mark paid" button. Salaries come from the Team tab.</div>
          {fin.recurring.map((r) => (
            <div key={r.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", fontSize: 13, marginBottom: 6, opacity: r.archived ? 0.5 : 1 }}>
              <span>{r.name} · {catName(r.category_id)} · {egp(r.default_amount)}{r.archived ? " (hidden)" : ""}</span>
              <button style={{ ...btnGhost, padding: "3px 8px", fontSize: 11 }} onClick={() => recAction.run(() => act((t) => db.update("recurring_expenses", r.id, { archived: !r.archived }, t)))}>{r.archived ? "Show" : "Hide"}</button>
            </div>
          ))}
          <div style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 8 }}>
            <input style={inputStyle} placeholder="Name (e.g. Office rent)" value={rec.name} onChange={(e) => setRec((s) => ({ ...s, name: e.target.value }))} />
            <SelectWithAdd value={rec.categoryId} onChange={(v) => setRec((s) => ({ ...s, categoryId: v }))} placeholder="Category"
              options={fin.categories.filter((c) => !c.archived)} onAdd={addCategory} />
            <input type="number" style={inputStyle} placeholder="Usual monthly amount" value={rec.amount} onChange={(e) => setRec((s) => ({ ...s, amount: e.target.value }))} />
            <button style={btnPrimary} disabled={recAction.busy} onClick={() => recAction.run(async () => {
              if (!rec.name.trim()) throw new Error("Enter a name.");
              await act((t) => db.insert("recurring_expenses", { name: rec.name.trim(), category_id: rec.categoryId || null, default_amount: num(rec.amount) }, t));
              setRec({ name: "", categoryId: "", amount: "" });
            })}>Add fixed item</button>
          </div>
          <FinError text={recAction.error} />
        </div>
      </div>
    </>
  );
}

// =====================================================================
// ---------- FINANCE: my earnings (everyone who isn't Admin / CEO) ----------
// =====================================================================
function MyEarnings({ ctx }) {
  const { fin, profile, users, calc, targetsMap, thresholds, userName, dealTitleById } = ctx;
  const [q, setQ] = useState(currentQuarterKey());
  const qKeys = [...new Set(fin.txns.filter((t) => t.kind === "commission_in").map((t) => quarterKeyOf(t.occurred_at)))];
  const myLines = calc.lines.filter((l) => l.beneficiaryId === profile.id);
  const allEarned = round2(myLines.reduce((s, l) => s + l.entitled, 0));
  const allPaid = round2(myLines.reduce((s, l) => s + l.paid, 0));
  const quarterEarned = round2(myLines.reduce((s, l) => s + l.detail.filter((x) => x.quarter === q).reduce((a, x) => a + x.amount, 0), 0));
  const target = num(targetsMap[profile.id]);
  const achieved = calc.achievement(profile.id, q);
  const pct = target ? (achieved / target) * 100 : 0;
  const tier = calc.tierOf(profile.id, q);
  const next = thresholds[tier + 1];
  const needed = next !== undefined && target ? Math.max(0, (num(next) / 100) * target - achieved) : null;
  const salary = fin.salaries.find((s) => s.user_id === profile.id);
  const myPlans = fin.rates.filter((r) => r.beneficiary_id === profile.id);
  const team = getSubtreeIds(users, profile.id).filter((id) => id !== profile.id).map((id) => users.find((u) => u.id === id)).filter(Boolean);
  const teamWithTargets = team.filter((u) => targetsMap[u.id] !== undefined);
  const salaryPayments = fin.txns.filter((t) => t.kind === "salary" && t.beneficiary_id === profile.id).sort((a, b) => new Date(b.occurred_at) - new Date(a.occurred_at)).slice(0, 6);

  return (
    <>
      <FinTitle right={<PeriodPicker value={q} onChange={setQ} options={quarterOptions(qKeys)} />}>My earnings</FinTitle>
      <div style={{ ...finCard, marginBottom: 14 }}>
        <div style={{ display: "flex", justifyContent: "space-between", flexWrap: "wrap", gap: 8, marginBottom: 8 }}>
          <div style={{ fontWeight: 600, color: COLORS.navy }}>My target · {quarterLabel(q)}</div>
          <Badge tone={tier > 0 ? "active" : "neutral"}>{tierLabel(tier, thresholds)}</Badge>
        </div>
        {target ? (
          <>
            <TargetBar pct={pct} thresholds={thresholds} />
            <div style={{ display: "flex", justifyContent: "space-between", flexWrap: "wrap", gap: 8, fontSize: 12.5, marginTop: 8 }}>
              <span><b>{egp(achieved)}</b> of {egp(target)} ({round2(pct)}%)</span>
              <span style={{ color: COLORS.textMuted }}>{needed !== null ? `${egp(needed)} more to reach ${tierLabel(tier + 1, thresholds)}` : "You're on the top tier 🎉"}</span>
            </div>
          </>
        ) : <div style={{ fontSize: 13, color: COLORS.textMuted }}>No target set for you yet.</div>}
      </div>

      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 14 }}>
        <FinStat label={`Earned in ${quarterLabel(q).split(" (")[0]}`} value={egp(quarterEarned)} tone="success" />
        <FinStat label="Earned (all time)" value={egp(allEarned)} />
        <FinStat label="Paid to me" value={egp(allPaid)} />
        <FinStat label="Still owed to me" value={egp(allEarned - allPaid)} tone={allEarned - allPaid > 0.5 ? "danger" : undefined} />
        {salary && <FinStat label="Monthly salary" value={egp(salary.monthly_salary)} />}
      </div>

      {myPlans.length > 0 && (
        <div style={{ marginBottom: 14 }}>
          <div style={{ fontWeight: 600, fontSize: 14, color: COLORS.navy, marginBottom: 8 }}>My commission rates</div>
          <TableWrap>
            <thead><tr><th style={thStyle}>When a deal is closed by</th>{thresholds.map((t, i) => <th key={i} style={thNum}>{i === 0 ? "Base" : `From ${t}%`}</th>)}</tr></thead>
            <tbody>
              {myPlans.map((r) => (
                <tr key={r.seller_id}>
                  <td style={tdStyle}>{r.seller_id === profile.id ? "Me" : userName(r.seller_id)}</td>
                  {thresholds.map((_, i) => <td key={i} style={tdNum}>{rateAt(r.rates, i)}%</td>)}
                </tr>
              ))}
            </tbody>
          </TableWrap>
        </div>
      )}

      {teamWithTargets.length > 0 && (
        <div style={{ marginBottom: 14 }}>
          <div style={{ fontWeight: 600, fontSize: 14, color: COLORS.navy, marginBottom: 8 }}>My team's targets</div>
          <TableWrap>
            <thead><tr><th style={thStyle}>Person</th><th style={thNum}>Target</th><th style={thNum}>Achieved</th><th style={thStyle}>Progress</th><th style={thNum}>%</th><th style={thStyle}>Tier</th><th style={thStyle}>Next</th></tr></thead>
            <tbody>{teamWithTargets.map((u) => <TargetRow key={u.id} u={u} q={q} ctx={ctx} />)}</tbody>
          </TableWrap>
        </div>
      )}

      <div style={{ fontWeight: 600, fontSize: 14, color: COLORS.navy, marginBottom: 8 }}>My commissions by deal</div>
      {myLines.length === 0 ? <div style={{ color: COLORS.textMuted, fontSize: 13 }}>No approved deals with collected commission yet.</div> : (
        <TableWrap>
          <thead><tr><th style={thStyle}>Deal</th><th style={thStyle}>Rate</th><th style={thNum}>Earned</th><th style={thNum}>Paid</th><th style={thNum}>Remaining</th></tr></thead>
          <tbody>
            {myLines.map((l) => (
              <tr key={l.dealId}>
                <td style={{ ...tdStyle, whiteSpace: "normal" }}>{dealTitleById(l.dealId)}</td>
                <td style={{ ...tdStyle, color: COLORS.textMuted }}>{[...new Set(l.detail.map((x) => `${x.rate}%${x.level > 0 ? ` on ${userName(x.agentId)}` : ""}`))].join(", ")}</td>
                <td style={tdNum}>{egp(l.entitled)}</td>
                <td style={tdNum}>{egp(l.paid)}</td>
                <td style={{ ...tdNum, fontWeight: 700, color: l.remaining > 0.5 ? COLORS.danger : COLORS.success }}>{egp(l.remaining)}</td>
              </tr>
            ))}
          </tbody>
        </TableWrap>
      )}

      {salaryPayments.length > 0 && (
        <div style={{ marginTop: 14 }}>
          <div style={{ fontWeight: 600, fontSize: 14, color: COLORS.navy, marginBottom: 8 }}>Recent salary payments</div>
          <div style={{ fontSize: 13, display: "flex", flexDirection: "column", gap: 4 }}>
            {salaryPayments.map((t) => <div key={t.id}>{formatDate(t.occurred_at)} — {egpFull(t.amount)}</div>)}
          </div>
        </div>
      )}
    </>
  );
}

// =====================================================================
// ---------- FINANCE: the section itself ----------
// =====================================================================
function FinanceSection({ profile, users, fin, act, getProjectInfo, units, onNewDeal, onEditDeal }) {
  const isAdmin = isFinanceAdmin(profile);
  const [tab, setTab] = useState(isAdmin ? "overview" : "earnings");
  const thresholds = (fin.settings?.tier_thresholds || [0, 70, 100]).map(num);
  const targetsMap = useMemo(() => Object.fromEntries(fin.targets.map((t) => [t.user_id, num(t.quarterly_target)])), [fin.targets]);
  const calc = useMemo(() => computeFinance({
    deals: fin.deals, dealAgents: fin.dealAgents, dealRates: fin.dealRates, txns: fin.txns, targets: targetsMap, thresholds,
  }), [fin, targetsMap]); // eslint-disable-line
  const balances = useMemo(() => accountBalances(fin.accounts, fin.txns), [fin.accounts, fin.txns]);
  const userName = (id) => users.find((u) => u.id === id)?.name || "—";
  const accountName = (id) => fin.accounts.find((a) => a.id === id)?.name || "—";
  const dealTitle = (d) => {
    if (!d) return "—";
    const unit = units.find((u) => u.id === d.unit_id);
    const unitText = unit ? `${unit.type} · ${unit.unitNumber} · ${getProjectInfo(unit).name}` : d.unit_label;
    return [unitText, d.client_label].filter(Boolean).join(" — ") || "Deal";
  };
  const dealTitleById = (id) => dealTitle(fin.deals.find((d) => d.id === id));
  const addCategory = async (name) => {
    let id = null;
    await act(async (t) => {
      const rows = await db.insert("expense_categories", { name }, t);
      id = rows && rows[0] && rows[0].id;
    });
    return id;
  };
  const people = users.filter((u) => u.role !== "pending").sort((a, b) => a.name.localeCompare(b.name));
  const charityPct = num(fin.settings?.charity_pct);
  const ctx = { fin, users, profile, isAdmin, calc, thresholds, charityPct, targetsMap, balances, userName, accountName, dealTitle, dealTitleById, act, onNewDeal, onEditDeal, addCategory };

  if (fin.error) {
    return (
      <div style={{ ...finCard, color: COLORS.danger, fontSize: 13.5 }}>
        Finance data could not be loaded: {fin.error}
        <div style={{ color: COLORS.textMuted, marginTop: 6 }}>If this is the first time, run <code>sql/add-finance-module.sql</code> in the Supabase SQL editor.</div>
      </div>
    );
  }
  if (!fin.loaded) return <div style={{ color: COLORS.textMuted, fontSize: 14 }}>Loading finance…</div>;

  const pendingCount = fin.deals.filter((d) => d.status === "pending").length;
  const tabs = isAdmin
    ? [
        { id: "overview", label: "Overview" },
        { id: "approvals", label: `Approvals${pendingCount ? ` (${pendingCount})` : ""}` },
        { id: "deals", label: "Deals & commissions" },
        { id: "targets", label: "Targets" },
        { id: "expenses", label: "Expenses" },
        { id: "treasury", label: "Treasury & reports" },
        { id: "team", label: "Team plans" },
        { id: "settings", label: "Settings" },
      ]
    : [
        { id: "earnings", label: "My earnings" },
        { id: "deals", label: "Deals" },
      ];

  return (
    <div>
      <div style={{ display: "flex", gap: 4, flexWrap: "wrap", marginBottom: 16, borderBottom: `1px solid ${COLORS.border}`, paddingBottom: 8 }}>
        {tabs.map((t) => (
          <button key={t.id} onClick={() => setTab(t.id)} style={{
            padding: "7px 12px", borderRadius: 8, border: "none", cursor: "pointer", fontSize: 12.5, fontWeight: 500,
            background: tab === t.id ? COLORS.creamDark : "transparent", color: tab === t.id ? COLORS.navy : COLORS.textMuted,
          }}>{t.label}</button>
        ))}
      </div>
      {tab === "overview" && isAdmin && <FinOverview ctx={ctx} goTab={setTab} />}
      {tab === "approvals" && isAdmin && <FinApprovals ctx={ctx} />}
      {tab === "deals" && <FinDeals ctx={ctx} />}
      {tab === "targets" && isAdmin && <FinTargets ctx={ctx} people={people} />}
      {tab === "expenses" && isAdmin && <FinExpenses ctx={ctx} />}
      {tab === "treasury" && isAdmin && <FinTreasury ctx={ctx} />}
      {tab === "team" && isAdmin && <FinTeam ctx={ctx} people={people} />}
      {tab === "settings" && isAdmin && <FinSettings ctx={ctx} />}
      {tab === "earnings" && !isAdmin && <MyEarnings ctx={ctx} />}
    </div>
  );
}

export default function App() {
  const [session, setSession] = useState(() => loadSession()); // { access_token, refresh_token, user }
  const [profile, setProfile] = useState(null);
  const [users, setUsers] = useState([]);
  const [developers, setDevelopers] = useState([]);
  const [projects, setProjects] = useState([]);
  const [units, setUnits] = useState([]);
  const [clients, setClients] = useState([]);
  const [clientActivity, setClientActivity] = useState([]);
  const [clientProjectLinks, setClientProjectLinks] = useState([]);
  const [clientUnitLinks, setClientUnitLinks] = useState([]);
  const [attendance, setAttendance] = useState([]);
  const EMPTY_FIN = { loaded: false, error: "", deals: [], dealAgents: [], dealRates: [], txns: [], accounts: [], categories: [], recurring: [], targets: [], salaries: [], rates: [], settings: null };
  const [fin, setFin] = useState(EMPTY_FIN);
  const [dealModal, setDealModal] = useState(null); // { initial } | { editing: { deal, agents } }
  const [dataLoading, setDataLoading] = useState(() => !!loadSession());
  const [loadError, setLoadError] = useState("");

  const [tab, setTab] = useState("home");
  const [section, setSection] = useState("units");
  const [openUnit, setOpenUnit] = useState(null);
  const [editingUnit, setEditingUnit] = useState(null);
  const [viewedUserId, setViewedUserId] = useState(null);
  const [holdTarget, setHoldTarget] = useState(null);
  const [openClientId, setOpenClientId] = useState(null);
  const [stageChangeTarget, setStageChangeTarget] = useState(null);
  const [feedbackTarget, setFeedbackTarget] = useState(null);
  const [closeTarget, setCloseTarget] = useState(null);
  const [restoreTarget, setRestoreTarget] = useState(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [filters, setFilters] = useState({
    destination: "", developerId: "", projectId: "", type: "", finishing: "", deliveryDate: "",
    floorMin: "", floorMax: "", landAreaMin: "", landAreaMax: "", buaMin: "", buaMax: "",
    extraAreaMin: "", extraAreaMax: "", priceMin: "", priceMax: "", unitNumber: "", phase: "",
  });

  const token = session?.access_token;

  const decodeJwtExp = (jwt) => {
    try {
      return JSON.parse(atob(jwt.split(".")[1])).exp;
    } catch (e) {
      return 0;
    }
  };

  // Returns a valid (non-expired) access token, refreshing the session first if needed.
  const getValidToken = async () => {
    if (!session) return null;
    const exp = decodeJwtExp(session.access_token);
    const now = Math.floor(Date.now() / 1000);
    if (exp - now > 30) return session.access_token;
    const refreshed = await auth.refresh(session.refresh_token);
    saveSession(refreshed);
    setSession(refreshed);
    return refreshed.access_token;
  };

  // --- Load all data once we have a session ---
  const fetchAllRaw = async (currentSession) => {
    const t = currentSession.access_token;
    const [profilesRows, devsRows, projsRows, unitsRows, salesRows, clientsRows, activityRows, cProjRows, cUnitRows, attendanceRows] = await Promise.all([
      db.select("profiles", "", t),
      db.select("developers", "&order=name", t),
      db.select("projects", "&order=name", t),
      db.select("units", "&order=created_at.desc", t),
      db.select("unit_sales", "", t),
      db.select("clients", "&order=updated_at.desc", t),
      db.select("client_activity", "&order=changed_at.desc", t),
      db.select("client_projects", "", t),
      db.select("client_units", "", t),
      db.select("attendance", "&order=checked_in_at.desc", t),
    ]);
    const profiles = (profilesRows || []).map(mapProfile);
    setUsers(profiles);
    setDevelopers((devsRows || []).map(mapDeveloper));
    setProjects((projsRows || []).map(mapProject));

    const salesByUnit = {};
    (salesRows || []).forEach((row) => {
      if (!salesByUnit[row.unit_id]) salesByUnit[row.unit_id] = [];
      salesByUnit[row.unit_id].push(row.sales_id);
    });
    setUnits((unitsRows || []).map((row) => mapUnit(row, salesByUnit[row.id])));

    setClients((clientsRows || []).map(mapClient));
    setClientActivity((activityRows || []).map(mapActivity));
    setClientProjectLinks(cProjRows || []);
    setClientUnitLinks(cUnitRows || []);
    setAttendance((attendanceRows || []).map(mapAttendance));

    const me = profiles.find((p) => p.id === currentSession.user.id);
    setProfile(me || null);
    loadFinance(t);
  };

  // Finance loads separately so a problem there never blocks the rest of the CRM
  const loadFinance = async (t) => {
    try {
      const [deals, dealAgents, dealRates, txns, accounts, categories, recurring, targets, salaries, rates, settingsRows] = await Promise.all([
        db.selectAll("deals", "&order=created_at.desc", t),
        db.selectAll("deal_agents", "", t),
        db.selectAll("deal_rates", "", t),
        db.selectAll("finance_transactions", "&order=occurred_at.asc", t),
        db.select("finance_accounts", "&order=created_at", t),
        db.select("expense_categories", "&order=name", t),
        db.select("recurring_expenses", "&order=name", t),
        db.select("staff_targets", "", t),
        db.select("staff_salaries", "", t),
        db.select("commission_rates", "", t),
        db.select("finance_settings", "", t),
      ]);
      setFin({
        loaded: true, error: "", deals, dealAgents, dealRates, txns,
        accounts: accounts || [], categories: categories || [], recurring: recurring || [],
        targets: targets || [], salaries: salaries || [], rates: rates || [], settings: (settingsRows || [])[0] || null,
      });
    } catch (err) {
      setFin((f) => ({ ...f, error: err.message || "Could not load finance data" }));
    }
  };
  const refreshFinance = async () => loadFinance(await getValidToken());

  // Every finance change goes through here: run it, then reload finance
  // (and units/clients too when approving/cancelling, since those change them)
  const finAct = async (fn, opts = {}) => {
    const t = await getValidToken();
    await fn(t);
    await loadFinance(t);
    if (opts.full) { await refreshUnits(); await refreshClients(); }
  };

  const saveDeal = async ({ deal, agents, approveNow, accountId }) => {
    const t = await getValidToken();
    let dealId;
    if (dealModal && dealModal.editing) {
      dealId = dealModal.editing.deal.id;
      await db.update("deals", dealId, deal, t);
      await db.removeWhere("deal_agents", `deal_id=eq.${dealId}`, t);
    } else {
      const created = await db.insert("deals", { ...deal, created_by: profile.id }, t);
      dealId = (Array.isArray(created) ? created[0] : created).id;
    }
    await db.insert("deal_agents", agents.map((a) => ({ ...a, deal_id: dealId })), t);
    if (approveNow) {
      await db.rpc("approve_deal", { p_deal: dealId, p_account: accountId || null, p_collected_at: dateInputToIso(deal.deal_date) }, t);
    }
    setDealModal(null);
    await loadFinance(t);
    if (approveNow) { await refreshUnits(); await refreshClients(); }
    if (!isFinanceAdmin(profile)) window.alert("Deal sent for approval ✓");
  };

  const fetchAll = async (currentSession) => {
    setDataLoading(true);
    setLoadError("");
    try {
      await fetchAllRaw(currentSession);
    } catch (err) {
      setLoadError(err.message || "Could not load data.");
    } finally {
      setDataLoading(false);
    }
  };

  // --- Restore a saved session on page load/refresh ---
  useEffect(() => {
    if (!session) return;
    (async () => {
      try {
        await fetchAllRaw(session);
      } catch (err) {
        try {
          const refreshed = await auth.refresh(session.refresh_token);
          saveSession(refreshed);
          setSession(refreshed);
          await fetchAllRaw(refreshed);
        } catch (err2) {
          clearSession();
          setSession(null);
        }
      } finally {
        setDataLoading(false);
      }
    })();
    // eslint-disable-next-line
  }, []);

  // Keep finance numbers fresh while someone is looking at them
  useEffect(() => {
    if (!session || section !== "finance") return;
    const id = setInterval(() => { refreshFinance().catch(() => {}); }, 60000);
    return () => clearInterval(id);
    // eslint-disable-next-line
  }, [section, session]);

  const handleAuthed = (newSession) => {
    saveSession(newSession);
    setSession(newSession);
    fetchAll(newSession);
  };

  const refreshUsers = async () => {
    const rows = await db.select("profiles", "", await getValidToken());
    const mapped = (rows || []).map(mapProfile);
    setUsers(mapped);
    setProfile(mapped.find((p) => p.id === session.user.id) || null);
  };
  const refreshCatalog = async () => {
    const [devsRows, projsRows] = await Promise.all([
      db.select("developers", "&order=name", await getValidToken()),
      db.select("projects", "&order=name", await getValidToken()),
    ]);
    setDevelopers((devsRows || []).map(mapDeveloper));
    setProjects((projsRows || []).map(mapProject));
  };
  const refreshUnits = async () => {
    const [unitsRows, salesRows] = await Promise.all([
      db.select("units", "&order=created_at.desc", await getValidToken()),
      db.select("unit_sales", "", await getValidToken()),
    ]);
    const salesByUnit = {};
    (salesRows || []).forEach((row) => {
      if (!salesByUnit[row.unit_id]) salesByUnit[row.unit_id] = [];
      salesByUnit[row.unit_id].push(row.sales_id);
    });
    setUnits((unitsRows || []).map((row) => mapUnit(row, salesByUnit[row.id])));
  };

  const refreshClients = async () => {
    const t = await getValidToken();
    const [clientsRows, activityRows, cProjRows, cUnitRows] = await Promise.all([
      db.select("clients", "&order=updated_at.desc", t),
      db.select("client_activity", "&order=changed_at.desc", t),
      db.select("client_projects", "", t),
      db.select("client_units", "", t),
    ]);
    setClients((clientsRows || []).map(mapClient));
    setClientActivity((activityRows || []).map(mapActivity));
    setClientProjectLinks(cProjRows || []);
    setClientUnitLinks(cUnitRows || []);
  };

  const checkIn = async ({ lat, lng, distance }) => {
    const t = await getValidToken();
    await db.insert("attendance", { user_id: profile.id, lat, lng, distance_meters: distance }, t);
    const rows = await db.select("attendance", "&order=checked_in_at.desc", t);
    setAttendance((rows || []).map(mapAttendance));
  };

  const addClient = async (form) => {
    const t = await getValidToken();
    const [created] = await db.insert("clients", clientToDbRow(form, profile.id), t);
    await db.insert("client_activity", { client_id: created.id, action: "created", new_value: form.stage, note: form.feedback, changed_by: profile.id }, t);
    await refreshClients();
  };

  const changeClientStage = async (client, { newStage, note, meetingAt }) => {
    const t = await getValidToken();
    await db.update("clients", client.id, {
      stage: newStage,
      previous_stage: client.stage,
      meeting_at: meetingAt,
    }, t);
    await db.insert("client_activity", {
      client_id: client.id, action: "stage_change", field_name: "stage",
      old_value: client.stage, new_value: newStage, note, changed_by: profile.id,
    }, t);
    setStageChangeTarget(null);
    await refreshClients();
  };

  const addClientFeedback = async (client, note) => {
    const t = await getValidToken();
    await db.insert("client_activity", { client_id: client.id, action: "note", note, changed_by: profile.id }, t);
    setFeedbackTarget(null);
    await refreshClients();
  };

  const closeClient = async (client, { reason, note }) => {
    const t = await getValidToken();
    await db.update("clients", client.id, {
      stage: "closed",
      previous_stage: client.stage,
      closed_reason: reason,
      closed_note: reason === "other" ? note : null,
    }, t);
    await db.insert("client_activity", {
      client_id: client.id, action: "closed", field_name: "stage",
      old_value: client.stage, new_value: "closed",
      note: reason === "other" ? note : CLOSE_REASON_LABEL[reason],
      changed_by: profile.id,
    }, t);
    setCloseTarget(null);
    setOpenClientId(null);
    await refreshClients();
  };

  const restoreClient = async (client, { newStage, note }) => {
    const t = await getValidToken();
    await db.update("clients", client.id, {
      stage: newStage,
      previous_stage: client.stage,
      closed_reason: null,
      closed_note: null,
    }, t);
    await db.insert("client_activity", {
      client_id: client.id, action: "stage_change", field_name: "stage",
      old_value: client.stage, new_value: newStage, note, changed_by: profile.id,
    }, t);
    setRestoreTarget(null);
    await refreshClients();
  };

  const toggleClientProjectLink = async (client, projectId) => {
    const t = await getValidToken();
    const exists = clientProjectLinks.some((l) => l.client_id === client.id && l.project_id === projectId);
    if (exists) {
      await db.removeWhere("client_projects", `client_id=eq.${client.id}&project_id=eq.${projectId}`, t);
    } else {
      await db.insert("client_projects", { client_id: client.id, project_id: projectId }, t);
      const proj = projects.find((p) => p.id === projectId);
      await db.insert("client_activity", { client_id: client.id, action: "project_link", new_value: proj?.name || projectId, changed_by: profile.id }, t);
    }
    await refreshClients();
  };

  const toggleClientUnitLink = async (client, unitId) => {
    const t = await getValidToken();
    const exists = clientUnitLinks.some((l) => l.client_id === client.id && l.unit_id === unitId);
    if (exists) {
      await db.removeWhere("client_units", `client_id=eq.${client.id}&unit_id=eq.${unitId}`, t);
    } else {
      await db.insert("client_units", { client_id: client.id, unit_id: unitId }, t);
      const u = units.find((uu) => uu.id === unitId);
      await db.insert("client_activity", { client_id: client.id, action: "unit_link", new_value: u?.unitNumber || unitId, changed_by: profile.id }, t);
    }
    await refreshClients();
  };

  const visibleSalesIds = useMemo(() => {
    if (!profile) return [];
    if (profile.role === "admin" || profile.role === "ceo") return users.map((u) => u.id);
    return getSubtreeIds(users, profile.id);
  }, [profile, users]);

  const canSeeOwner = (unit) => profile?.role === "admin" || profile?.role === "ceo" || unit.salesIds.some((id) => visibleSalesIds.includes(id));
  const getHandledBy = (unit) => {
    const primary = users.find((u) => u.id === unit.salesIds[0]);
    return primary ? { id: primary.id, name: primary.name, phone: primary.phone, avatarUrl: primary.avatarUrl } : null;
  };
  const getProjectInfo = (unit) => {
    const project = projects.find((p) => p.id === unit.projectId);
    const developer = project ? developers.find((d) => d.id === project.developerId) : null;
    return {
      name: project?.name || "—",
      destination: project?.destination || "—",
      developerName: developer?.name || "—",
      developerId: project?.developerId || "",
    };
  };
  const pendingDeleteUnits = units.filter((u) => u.status === "pending_delete");

  const myUnits = units.filter((u) => u.salesIds.some((id) => visibleSalesIds.includes(id)) && u.status !== "hold" && u.status !== "sold");
  const holdUnits = units.filter((u) => u.status === "hold" && (profile?.role === "admin" || profile?.role === "ceo" || u.salesIds.some((id) => visibleSalesIds.includes(id))));
  const randomUnits = useMemo(() => [...units].filter((u) => u.status === "active").sort(() => 0.5 - Math.random()).slice(0, 6), [units]);

  const filteredUnits = units.filter((u) => {
    if (u.status !== "active") return false;
    const info = getProjectInfo(u);
    if (filters.destination && info.destination !== filters.destination) return false;
    if (filters.developerId && info.developerId !== filters.developerId) return false;
    if (filters.projectId && u.projectId !== filters.projectId) return false;
    if (filters.type && u.type !== filters.type) return false;
    if (filters.finishing && u.finishing !== filters.finishing) return false;
    if (filters.deliveryDate && u.deliveryDate !== filters.deliveryDate) return false;
    if (filters.floorMin && Number(u.floor) < Number(filters.floorMin)) return false;
    if (filters.floorMax && Number(u.floor) > Number(filters.floorMax)) return false;
    if (filters.landAreaMin && Number(u.landArea || 0) < Number(filters.landAreaMin)) return false;
    if (filters.landAreaMax && Number(u.landArea || 0) > Number(filters.landAreaMax)) return false;
    if (filters.buaMin && Number(u.bua || 0) < Number(filters.buaMin)) return false;
    if (filters.buaMax && Number(u.bua || 0) > Number(filters.buaMax)) return false;
    if (filters.extraAreaMin && Number(u.extraArea || 0) < Number(filters.extraAreaMin)) return false;
    if (filters.extraAreaMax && Number(u.extraArea || 0) > Number(filters.extraAreaMax)) return false;
    if (filters.priceMin && Number(u.totalPrice) < Number(filters.priceMin)) return false;
    if (filters.priceMax && Number(u.totalPrice) > Number(filters.priceMax)) return false;
    if (filters.unitNumber && !u.unitNumber.toLowerCase().includes(filters.unitNumber.toLowerCase())) return false;
    if (filters.phase && !(u.phase || "").toLowerCase().includes(filters.phase.toLowerCase())) return false;
    return true;
  });

  // --- Global search (units + people) ---
  const searchQ = searchQuery.trim().toLowerCase();
  const searchMatchedUsers = searchQ
    ? users.filter((u) => u.role !== "admin" && u.role !== "pending" && u.name.toLowerCase().includes(searchQ))
    : [];
  const searchMatchedUnits = searchQ
    ? units.filter((u) => {
        if (u.status !== "active") return false;
        const info = getProjectInfo(u);
        const haystack = [
          u.type, u.phase, u.unitNumber, u.description, floorLabel(u.floor),
          info.name, info.destination, info.developerName,
        ].join(" ").toLowerCase();
        return haystack.includes(searchQ);
      })
    : [];

  // --- Unit CRUD ---
  const addUnit = async (unitForm, photoFileList) => {
    const uploadedUrls = [];
    for (let i = 0; i < photoFileList.length; i++) {
      const file = photoFileList[i];
      const path = `${session.user.id}/${Date.now()}-${i}-${file.name}`;
      const url = await storage.upload("unit-photos", path, file, await getValidToken());
      uploadedUrls.push(url);
    }
    const row = unitToDbRow({ ...unitForm, photos: uploadedUrls }, profile.id);
    const inserted = await db.insert("units", row, await getValidToken());
    const newUnit = Array.isArray(inserted) ? inserted[0] : inserted;
    await db.insert("unit_sales", { unit_id: newUnit.id, sales_id: profile.id }, await getValidToken());
    await refreshUnits();
  };

  const updateUnit = async (unit, formData, newPhotoFiles) => {
    const uploadedUrls = [];
    for (let i = 0; i < newPhotoFiles.length; i++) {
      const file = newPhotoFiles[i];
      const path = `${session.user.id}/${Date.now()}-${i}-${file.name}`;
      const url = await storage.upload("unit-photos", path, file, await getValidToken());
      uploadedUrls.push(url);
    }
    const finalPhotos = [...formData.existingPhotos, ...uploadedUrls];
    await db.update("units", unit.id, unitEditToDbRow({ ...formData, photos: finalPhotos }), await getValidToken());
    await refreshUnits();
  };

  const confirmHold = async (reason) => {
    await db.update("units", holdTarget.id, { status: "hold", hold_reason: reason }, await getValidToken());
    setHoldTarget(null);
    await refreshUnits();
  };
  const releaseHold = async (unit) => {
    await db.update("units", unit.id, { status: "active", hold_reason: null }, await getValidToken());
    await refreshUnits();
  };
  const requestDelete = async (unit) => {
    await db.update("units", unit.id, { status: "pending_delete", previous_status: unit.status }, await getValidToken());
    setOpenUnit(null);
    await refreshUnits();
  };
  const deleteUnitDirectly = async (unit) => {
    await db.remove("units", unit.id, await getValidToken());
    setOpenUnit(null);
    await refreshUnits();
  };
  const approveDelete = async (unit) => {
    await db.remove("units", unit.id, await getValidToken());
    await refreshUnits();
  };
  const rejectDelete = async (unit) => {
    await db.update("units", unit.id, { status: unit.previousStatus || "active", previous_status: null }, await getValidToken());
    await refreshUnits();
  };
  const reassignUnit = async (unit, newSalesId) => {
    await db.removeWhere("unit_sales", `unit_id=eq.${unit.id}`, await getValidToken());
    await db.insert("unit_sales", { unit_id: unit.id, sales_id: newSalesId }, await getValidToken());
    await refreshUnits();
  };

  // --- User management ---
  const approveUser = async (id, changes) => {
    await db.update("profiles", id, { role: changes.role, manager_id: changes.managerId }, await getValidToken());
    await refreshUsers();
  };
  const editUser = async (id, changes) => {
    await db.update("profiles", id, { role: changes.role, manager_id: changes.managerId }, await getValidToken());
    await refreshUsers();
  };
  const updateMyProfile = async (changes) => {
    const dbChanges = { name: changes.name, phone: changes.phone };
    if (changes.avatarUrl !== undefined) dbChanges.avatar_url = changes.avatarUrl;
    await db.update("profiles", profile.id, dbChanges, await getValidToken());
    await refreshUsers();
  };
  const uploadAvatar = async (file) => {
    const path = `avatars/${profile.id}-${Date.now()}-${file.name}`;
    return await storage.upload("unit-photos", path, file, await getValidToken());
  };
  const updateMyEmail = async (newEmail) => {
    await auth.updateUser(token, { email: newEmail });
  };
  const removeUser = async (id) => {
    await db.remove("profiles", id, await getValidToken());
    await refreshUsers();
    await refreshUnits();
  };

  // --- Developer / project management ---
  const addDeveloper = async (dev) => {
    await db.insert("developers", { name: dev.name }, await getValidToken());
    await refreshCatalog();
  };
  const removeDeveloper = async (id) => {
    await db.remove("developers", id, await getValidToken());
    await refreshCatalog();
  };
  const addProject = async (proj) => {
    await db.insert("projects", { name: proj.name, developer_id: proj.developerId, destination: proj.destination }, await getValidToken());
    await refreshCatalog();
  };
  const editProject = async (id, changes) => {
    await db.update("projects", id, { name: changes.name, developer_id: changes.developerId, destination: changes.destination }, await getValidToken());
    await refreshCatalog();
  };
  const removeProject = async (id) => {
    await db.remove("projects", id, await getValidToken());
    await refreshCatalog();
  };

  const signOut = async () => {
    await auth.signOut(await getValidToken());
    clearSession();
    setSession(null);
    setProfile(null);
    setUsers([]);
    setDevelopers([]);
    setProjects([]);
    setUnits([]);
    setClients([]);
    setClientActivity([]);
    setClientProjectLinks([]);
    setClientUnitLinks([]);
    setFin(EMPTY_FIN);
  };

  // --- Render states ---
  if (!session) return <AuthScreen onAuthed={handleAuthed} />;

  if (dataLoading) {
    return (
      <div style={{ minHeight: 480, display: "flex", alignItems: "center", justifyContent: "center", background: COLORS.cream, color: COLORS.textMuted, fontFamily: "-apple-system, Helvetica, Arial, sans-serif" }}>
        Loading…
      </div>
    );
  }

  if (loadError) {
    return (
      <div style={{ minHeight: 480, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 12, background: COLORS.cream, color: COLORS.danger, fontFamily: "-apple-system, Helvetica, Arial, sans-serif", padding: 20, textAlign: "center" }}>
        <div>Could not load data: {loadError}</div>
        <button onClick={() => fetchAll(session)} style={{ border: `1px solid ${COLORS.border}`, background: "#fff", padding: "8px 16px", borderRadius: 8, cursor: "pointer" }}>Retry</button>
      </div>
    );
  }

  if (!profile || profile.role === "pending") return <PendingScreen onSignOut={signOut} />;

  const finPending = isFinanceAdmin(profile) ? fin.deals.filter((d) => d.status === "pending").length : 0;
  const SECTIONS = [
    { id: "clients", label: "Clients", icon: MessageSquare },
    { id: "units", label: "Units", icon: Building2 },
    { id: "finance", label: finPending ? `Finance (${finPending})` : "Finance", icon: Wallet },
    { id: "profile", label: "My Profile", icon: UserRound },
  ];
  const UNITS_SUBNAV = [
    { id: "home", label: "Home", icon: Home },
    { id: "search", label: "Search", icon: Search },
    { id: "my", label: "My units", icon: User },
    { id: "all", label: "All units", icon: LayoutGrid },
    { id: "add", label: "Add unit", icon: PlusCircle },
    { id: "hold", label: "On hold", icon: PauseCircle },
  ];
  const PROFILE_SUBNAV = [{ id: "profile", label: "My profile", icon: UserRound }];
  if (profile.role === "admin" || profile.role === "ceo") {
    PROFILE_SUBNAV.push({ id: "dashboard", label: "Dashboard", icon: LayoutGrid });
    PROFILE_SUBNAV.push({ id: "reports", label: "Reports", icon: Users });
  }
  if (profile.role === "admin") {
    PROFILE_SUBNAV.push({ id: "users", label: "Manage users", icon: Users });
    PROFILE_SUBNAV.push({ id: "catalog", label: "Developers & projects", icon: Building2 });
    PROFILE_SUBNAV.push({ id: "deletions", label: "Deletion requests", icon: Trash2 });
  }
  const goSection = (id) => {
    setSection(id);
    if (id === "units") setTab("home");
    if (id === "profile") setTab("profile");
    setOpenClientId(null);
  };
  const currentSubNav = section === "units" ? UNITS_SUBNAV : section === "profile" ? PROFILE_SUBNAV : [];

  return (
    <div style={{ fontFamily: "-apple-system, Helvetica, Arial, sans-serif", background: COLORS.cream, minHeight: 560, borderRadius: 12, overflow: "hidden", border: `1px solid ${COLORS.border}` }}>
      {/* Top bar */}
      <div style={{ background: COLORS.navy, color: "#fff", padding: "10px 16px", display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, background: "#fff", padding: "4px 10px", borderRadius: 6 }}>
          <img src={LOGO_SRC} alt="Origin Real Estate" style={{ height: 28 }} />
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 14, fontSize: 13 }}>
          <CheckInWidget
            checkedInToday={attendance.find((a) => a.userId === profile.id && isToday(a.checkedInAt))}
            onCheckIn={checkIn}
          />
          <NotificationsBell
            clients={clients}
            activity={clientActivity}
            visibleSalesIds={visibleSalesIds}
            onOpenClient={(c) => { setSection("clients"); setOpenClientId(c.id); }}
          />
          <span>{profile.name} <span style={{ color: COLORS.gold }}>· {ROLE_LABEL[profile.role]}</span></span>
          <button onClick={signOut} style={{ background: "none", border: "none", color: "#fff", cursor: "pointer", display: "flex", alignItems: "center", gap: 4 }}>
            <LogOut size={14} /> Sign out
          </button>
        </div>
      </div>

      {/* Top-level sections */}
      <div style={{ display: "flex", gap: 4, padding: "10px 20px 0", background: "#fff", flexWrap: "wrap" }}>
        {SECTIONS.map((n) => (
          <button
            key={n.id}
            onClick={() => goSection(n.id)}
            style={{
              display: "flex", alignItems: "center", gap: 6, padding: "9px 16px", borderRadius: "8px 8px 0 0",
              border: "none", cursor: "pointer", fontSize: 13.5, fontWeight: 600,
              background: section === n.id ? COLORS.navy : "transparent",
              color: section === n.id ? "#fff" : COLORS.text,
            }}
          >
            <n.icon size={15} /> {n.label}
          </button>
        ))}
      </div>

      {/* Sub-nav */}
      {currentSubNav.length > 0 && (
        <div style={{ display: "flex", gap: 4, padding: "8px 20px", background: "#fff", borderBottom: `1px solid ${COLORS.border}`, flexWrap: "wrap" }}>
          {currentSubNav.map((n) => (
            <button
              key={n.id}
              onClick={() => setTab(n.id)}
              style={{
                display: "flex", alignItems: "center", gap: 6, padding: "7px 12px", borderRadius: 8,
                border: "none", cursor: "pointer", fontSize: 12.5, fontWeight: 500,
                background: tab === n.id ? COLORS.creamDark : "transparent",
                color: tab === n.id ? COLORS.navy : COLORS.textMuted,
              }}
            >
              <n.icon size={13} /> {n.label}
            </button>
          ))}
        </div>
      )}

      <div style={{ padding: 20 }}>
        {viewedUserId ? (
          <SalesProfile
            person={users.find((u) => u.id === viewedUserId)}
            units={units.filter((u) => u.salesIds.includes(viewedUserId) && u.status !== "pending_delete")}
            canSeeOwnerFn={canSeeOwner}
            projectInfoFn={getProjectInfo}
            onOpen={setOpenUnit}
            onBack={() => setViewedUserId(null)}
          />
        ) : (
          <>
        {section === "units" && tab === "home" && (
          <>
            <div style={{ fontWeight: 600, fontSize: 16, color: COLORS.navy, marginBottom: 14 }}>Featured units</div>
            {randomUnits.length === 0 ? (
              <div style={{ color: COLORS.textMuted, fontSize: 14 }}>No units yet.</div>
            ) : (
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 14 }}>
                {randomUnits.map((u) => <UnitCard key={u.id} unit={u} projectInfo={getProjectInfo(u)} canSeeOwner={canSeeOwner(u)} handledBy={getHandledBy(u)} onOpen={setOpenUnit} onViewProfile={setViewedUserId} />)}
              </div>
            )}
          </>
        )}

        {section === "units" && tab === "search" && (
          <>
            <div style={{ fontWeight: 600, fontSize: 16, color: COLORS.navy, marginBottom: 14 }}>Search</div>
            <input
              style={{ ...inputStyle, marginBottom: 20 }}
              placeholder="Search units, people, projects, or locations…"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              autoFocus
            />
            {!searchQ ? (
              <div style={{ color: COLORS.textMuted, fontSize: 14 }}>Start typing to search.</div>
            ) : (
              <>
                {searchMatchedUsers.length > 0 && (
                  <div style={{ marginBottom: 24 }}>
                    <div style={{ fontWeight: 500, fontSize: 14, color: COLORS.navy, marginBottom: 10 }}>People</div>
                    <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                      {searchMatchedUsers.map((u) => (
                        <div
                          key={u.id}
                          onClick={() => setViewedUserId(u.id)}
                          style={{ display: "flex", alignItems: "center", gap: 10, background: "#fff", border: `1px solid ${COLORS.border}`, borderRadius: 8, padding: "10px 14px", cursor: "pointer" }}
                        >
                          <div style={{ width: 32, height: 32, borderRadius: "50%", overflow: "hidden", background: COLORS.creamDark, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                            {u.avatarUrl ? <img src={u.avatarUrl} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : <UserRound size={16} color={COLORS.textMuted} />}
                          </div>
                          <div>
                            <div style={{ fontSize: 13, fontWeight: 500 }}>{u.name}</div>
                            <div style={{ fontSize: 12, color: COLORS.textMuted }}>{ROLE_LABEL[u.role]}</div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                <div>
                  <div style={{ fontWeight: 500, fontSize: 14, color: COLORS.navy, marginBottom: 10 }}>Units ({searchMatchedUnits.length})</div>
                  {searchMatchedUnits.length === 0 ? (
                    <div style={{ color: COLORS.textMuted, fontSize: 14 }}>No matching units.</div>
                  ) : (
                    <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 14 }}>
                      {searchMatchedUnits.map((u) => <UnitCard key={u.id} unit={u} projectInfo={getProjectInfo(u)} canSeeOwner={canSeeOwner(u)} handledBy={getHandledBy(u)} onOpen={setOpenUnit} onViewProfile={setViewedUserId} />)}
                    </div>
                  )}
                </div>
              </>
            )}
          </>
        )}

        {section === "units" && tab === "my" && (
          <>
            <div style={{ fontWeight: 600, fontSize: 16, color: COLORS.navy, marginBottom: 14 }}>
              {profile.role === "sales_agent" ? "My units" : "My team's units"}
            </div>
            {myUnits.length === 0 ? (
              <div style={{ color: COLORS.textMuted, fontSize: 14 }}>No units assigned yet.</div>
            ) : (
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 14 }}>
                {myUnits.map((u) => <UnitCard key={u.id} unit={u} projectInfo={getProjectInfo(u)} canSeeOwner={canSeeOwner(u)} handledBy={getHandledBy(u)} onOpen={setOpenUnit} onViewProfile={setViewedUserId} />)}
              </div>
            )}
          </>
        )}

        {section === "units" && tab === "all" && (
          <>
            <div style={{ fontWeight: 600, fontSize: 16, color: COLORS.navy, marginBottom: 14 }}>All units</div>
            <div style={{ background: "#fff", padding: 16, borderRadius: 10, border: `1px solid ${COLORS.border}`, marginBottom: 16 }}>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))", gap: 12, marginBottom: 14 }}>
                <Select value={filters.destination} onChange={(v) => setFilters((f) => ({ ...f, destination: v, projectId: "" }))} options={DESTINATIONS} placeholder="Destination" />
                <select value={filters.developerId} onChange={(e) => setFilters((f) => ({ ...f, developerId: e.target.value, projectId: "" }))} style={{ ...inputStyle, appearance: "none" }}>
                  <option value="">Developer</option>
                  {developers.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
                </select>
                <select value={filters.projectId} onChange={(e) => setFilters((f) => ({ ...f, projectId: e.target.value }))} style={{ ...inputStyle, appearance: "none" }}>
                  <option value="">Project</option>
                  {projects
                    .filter((p) => (!filters.destination || p.destination === filters.destination) && (!filters.developerId || p.developerId === filters.developerId))
                    .map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
                </select>
                <Select value={filters.type} onChange={(v) => setFilters((f) => ({ ...f, type: v }))} options={TYPES} placeholder="Type" />
                <Select value={filters.finishing} onChange={(v) => setFilters((f) => ({ ...f, finishing: v }))} options={FINISHING} placeholder="Finishing" />
                <Select value={filters.deliveryDate} onChange={(v) => setFilters((f) => ({ ...f, deliveryDate: v }))} options={DELIVERY} placeholder="Delivery date" />
                <input style={inputStyle} placeholder="Unit number" value={filters.unitNumber} onChange={(e) => setFilters((f) => ({ ...f, unitNumber: e.target.value }))} />
                <input style={inputStyle} placeholder="Phase" value={filters.phase} onChange={(e) => setFilters((f) => ({ ...f, phase: e.target.value }))} />
              </div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: 20 }}>
                <RangeField label="Total price (EGP)" minValue={filters.priceMin} maxValue={filters.priceMax}
                  onMinChange={(v) => setFilters((f) => ({ ...f, priceMin: v }))} onMaxChange={(v) => setFilters((f) => ({ ...f, priceMax: v }))} />
                <RangeField label="Floor" minValue={filters.floorMin} maxValue={filters.floorMax}
                  onMinChange={(v) => setFilters((f) => ({ ...f, floorMin: v }))} onMaxChange={(v) => setFilters((f) => ({ ...f, floorMax: v }))} />
                <RangeField label="Land area (sqm)" minValue={filters.landAreaMin} maxValue={filters.landAreaMax}
                  onMinChange={(v) => setFilters((f) => ({ ...f, landAreaMin: v }))} onMaxChange={(v) => setFilters((f) => ({ ...f, landAreaMax: v }))} />
                <RangeField label="BUA (sqm)" minValue={filters.buaMin} maxValue={filters.buaMax}
                  onMinChange={(v) => setFilters((f) => ({ ...f, buaMin: v }))} onMaxChange={(v) => setFilters((f) => ({ ...f, buaMax: v }))} />
                <RangeField label="Extra area (sqm)" minValue={filters.extraAreaMin} maxValue={filters.extraAreaMax}
                  onMinChange={(v) => setFilters((f) => ({ ...f, extraAreaMin: v }))} onMaxChange={(v) => setFilters((f) => ({ ...f, extraAreaMax: v }))} />
              </div>
              <button
                onClick={() => setFilters({ destination: "", developerId: "", projectId: "", type: "", finishing: "", deliveryDate: "", floorMin: "", floorMax: "", landAreaMin: "", landAreaMax: "", buaMin: "", buaMax: "", extraAreaMin: "", extraAreaMax: "", priceMin: "", priceMax: "", unitNumber: "", phase: "" })}
                style={{ marginTop: 14, border: `1px solid ${COLORS.border}`, background: "#fff", padding: "7px 14px", borderRadius: 8, cursor: "pointer", fontSize: 12, color: COLORS.textMuted }}
              >
                Clear all filters
              </button>
            </div>
            <div style={{ fontSize: 12, color: COLORS.textMuted, marginBottom: 10 }}>{filteredUnits.length} units found</div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 14 }}>
              {filteredUnits.map((u) => <UnitCard key={u.id} unit={u} projectInfo={getProjectInfo(u)} canSeeOwner={canSeeOwner(u)} handledBy={getHandledBy(u)} onOpen={setOpenUnit} onViewProfile={setViewedUserId} />)}
            </div>
          </>
        )}

        {section === "units" && tab === "add" && (
          <>
            <div style={{ fontWeight: 600, fontSize: 16, color: COLORS.navy, marginBottom: 14 }}>{editingUnit ? "Edit unit" : "Add a new unit"}</div>
            <AddUnitForm
              onAdd={addUnit}
              onUpdate={updateUnit}
              currentUser={profile}
              developers={developers}
              projects={projects}
              editingUnit={editingUnit}
              onDoneEditing={() => setEditingUnit(null)}
            />
          </>
        )}

        {section === "units" && tab === "hold" && (
          <>
            <div style={{ fontWeight: 600, fontSize: 16, color: COLORS.navy, marginBottom: 14 }}>Units on hold</div>
            {holdUnits.length === 0 ? (
              <div style={{ color: COLORS.textMuted, fontSize: 14 }}>No units on hold.</div>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {holdUnits.map((u) => (
                  <div key={u.id} style={{ display: "flex", gap: 14, background: "#fff", border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: 12 }}>
                    <img src={u.photos[0]} alt="" style={{ width: 90, height: 70, objectFit: "cover", borderRadius: 6 }} />
                    <div style={{ flex: 1 }}>
                      <div style={{ fontWeight: 500, fontSize: 14, color: COLORS.navy }}>{u.type} · {u.unitNumber}</div>
                      <div style={{ fontSize: 12, color: COLORS.textMuted }}>{getProjectInfo(u).destination} · {getProjectInfo(u).name}</div>
                      <div style={{ fontSize: 12, color: COLORS.danger, marginTop: 4 }}>Reason: {u.holdReason}</div>
                    </div>
                    <button onClick={() => releaseHold(u)} style={{ alignSelf: "center", border: `1px solid ${COLORS.border}`, background: "#fff", padding: "7px 12px", borderRadius: 8, cursor: "pointer", fontSize: 12 }}>
                      Reactivate
                    </button>
                  </div>
                ))}
              </div>
            )}
          </>
        )}

        {section === "clients" && (
          <>
            {openClientId && openClientId !== "__new__" ? (
              (() => {
                const client = clients.find((c) => c.id === openClientId);
                if (!client) return <div style={{ color: COLORS.textMuted, fontSize: 13 }}>Client not found.</div>;
                const linkedUnitIds = clientUnitLinks.filter((l) => l.client_id === client.id).map((l) => l.unit_id);
                return (
                  <ClientProfile
                    client={client}
                    activity={clientActivity}
                    assignedUser={users.find((u) => u.id === client.assignedTo)}
                    projects={projects}
                    units={units}
                    developers={developers}
                    projectInfoFn={getProjectInfo}
                    linkedUnitIds={linkedUnitIds}
                    canManage={visibleSalesIds.includes(client.assignedTo)}
                    onBack={() => setOpenClientId(null)}
                    onChangeStage={() => setStageChangeTarget(client)}
                    onAddFeedback={() => setFeedbackTarget(client)}
                    onCloseLead={() => setCloseTarget(client)}
                    onRestore={() => setRestoreTarget(client)}
                    onOpenUnit={(u) => setOpenUnit(u)}
                    onToggleUnitLink={(uid) => toggleClientUnitLink(client, uid)}
                    onMarkSold={() => setDealModal({ initial: { clientId: client.id, unitId: linkedUnitIds.length === 1 ? linkedUnitIds[0] : "" } })}
                  />
                );
              })()
            ) : (
              <>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
                  <div style={{ fontWeight: 600, fontSize: 16, color: COLORS.navy }}>Clients</div>
                  <button onClick={() => setOpenClientId("__new__")} style={{ background: COLORS.navy, color: "#fff", border: "none", padding: "9px 16px", borderRadius: 8, cursor: "pointer", fontSize: 13, fontWeight: 600 }}>
                    + Add client
                  </button>
                </div>
                <ClientsList
                  clients={clients}
                  users={users}
                  projects={projects}
                  units={units}
                  clientUnitLinks={clientUnitLinks}
                  activity={clientActivity}
                  visibleSalesIds={visibleSalesIds}
                  currentUserId={profile.id}
                  isManager={profile.role !== "sales_agent"}
                  onOpenClient={(c) => setOpenClientId(c.id)}
                  onOpenUnit={(u) => setOpenUnit(u)}
                />
              </>
            )}

            {openClientId === "__new__" && (
              <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100, padding: 16 }}>
                <div style={{ background: "#fff", borderRadius: 12, padding: 22, width: "100%", maxWidth: 480, maxHeight: "90vh", overflowY: "auto" }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
                    <div style={{ fontWeight: 700, fontSize: 15, color: COLORS.navy }}>Add client</div>
                    <button onClick={() => setOpenClientId(null)} style={{ border: "none", background: "none", cursor: "pointer" }}><X size={18} /></button>
                  </div>
                  <AddClientForm
                    currentUser={profile}
                    assignableUsers={users.filter((u) => visibleSalesIds.includes(u.id))}
                    onAdd={async (form) => { await addClient(form); setOpenClientId(null); }}
                  />
                </div>
              </div>
            )}

            {stageChangeTarget && (
              <StageChangeModal
                client={stageChangeTarget}
                onCancel={() => setStageChangeTarget(null)}
                onConfirm={(payload) => changeClientStage(stageChangeTarget, payload)}
              />
            )}
            {feedbackTarget && (
              <AddFeedbackModal
                client={feedbackTarget}
                onCancel={() => setFeedbackTarget(null)}
                onConfirm={(note) => addClientFeedback(feedbackTarget, note)}
              />
            )}
            {closeTarget && (
              <CloseLeadModal
                client={closeTarget}
                onCancel={() => setCloseTarget(null)}
                onConfirm={(payload) => closeClient(closeTarget, payload)}
              />
            )}
            {restoreTarget && (
              <RestoreLeadModal
                client={restoreTarget}
                onCancel={() => setRestoreTarget(null)}
                onConfirm={(payload) => restoreClient(restoreTarget, payload)}
              />
            )}
          </>
        )}

        {section === "finance" && (
          <FinanceSection
            profile={profile}
            users={users}
            units={units}
            fin={fin}
            act={finAct}
            getProjectInfo={getProjectInfo}
            onNewDeal={(initial) => setDealModal({ initial })}
            onEditDeal={(deal) => setDealModal({ editing: { deal, agents: fin.dealAgents.filter((a) => a.deal_id === deal.id) } })}
          />
        )}

        {section === "profile" && tab === "dashboard" && (profile.role === "admin" || profile.role === "ceo") && (
          <Dashboard
            clients={clients}
            activity={clientActivity}
            users={users}
            visibleSalesIds={visibleSalesIds}
            onOpenClient={(c) => { setSection("clients"); setOpenClientId(c.id); }}
            attendance={attendance}
          />
        )}

        {section === "profile" && tab === "reports" && (profile.role === "admin" || profile.role === "ceo") && (
          <ReportsTab
            clients={clients}
            activity={clientActivity}
            users={users}
            units={units}
            visibleSalesIds={visibleSalesIds}
            onOpenClient={(c) => { setSection("clients"); setOpenClientId(c.id); }}
            onOpenUnit={(u) => setOpenUnit(u)}
            attendance={attendance}
          />
        )}

        {section === "profile" && tab === "profile" && (
          <>
            <div style={{ fontWeight: 600, fontSize: 16, color: COLORS.navy, marginBottom: 14 }}>My profile</div>
            <EditProfile profile={profile} currentEmail={session.user.email} onSave={updateMyProfile} onUploadAvatar={uploadAvatar} onUpdateEmail={updateMyEmail} />
          </>
        )}

        {section === "profile" && tab === "users" && profile.role === "admin" && (
          <>
            <div style={{ fontWeight: 600, fontSize: 16, color: COLORS.navy, marginBottom: 14 }}>Manage users</div>
            <ManageUsers users={users} onApprove={approveUser} onRemove={removeUser} onEdit={editUser} />
          </>
        )}

        {section === "profile" && tab === "catalog" && profile.role === "admin" && (
          <>
            <div style={{ fontWeight: 600, fontSize: 16, color: COLORS.navy, marginBottom: 14 }}>Developers and projects</div>
            <ManageCatalog
              developers={developers}
              projects={projects}
              onAddDeveloper={addDeveloper}
              onRemoveDeveloper={removeDeveloper}
              onAddProject={addProject}
              onEditProject={editProject}
              onRemoveProject={removeProject}
            />
          </>
        )}

        {section === "profile" && tab === "deletions" && profile.role === "admin" && (
          <>
            <div style={{ fontWeight: 600, fontSize: 16, color: COLORS.navy, marginBottom: 14 }}>Deletion requests</div>
            {pendingDeleteUnits.length === 0 ? (
              <div style={{ color: COLORS.textMuted, fontSize: 14 }}>No pending deletion requests.</div>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {pendingDeleteUnits.map((u) => (
                  <div key={u.id} style={{ display: "flex", gap: 14, background: "#fff", border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: 12 }}>
                    <img src={u.photos[0]} alt="" style={{ width: 90, height: 70, objectFit: "cover", borderRadius: 6 }} />
                    <div style={{ flex: 1 }}>
                      <div style={{ fontWeight: 500, fontSize: 14, color: COLORS.navy }}>{u.type} · {u.unitNumber}</div>
                      <div style={{ fontSize: 12, color: COLORS.textMuted }}>{getProjectInfo(u).destination} · {getProjectInfo(u).name}</div>
                      <div style={{ fontSize: 12, color: COLORS.textMuted, marginTop: 4 }}>Requested by {getHandledBy(u)?.name || "—"}</div>
                    </div>
                    <div style={{ display: "flex", gap: 8, alignSelf: "center" }}>
                      <button onClick={() => rejectDelete(u)} style={{ border: `1px solid ${COLORS.border}`, background: "#fff", padding: "7px 12px", borderRadius: 8, cursor: "pointer", fontSize: 12 }}>
                        Reject
                      </button>
                      <button onClick={() => approveDelete(u)} style={{ border: "none", background: COLORS.danger, color: "#fff", padding: "7px 12px", borderRadius: 8, cursor: "pointer", fontSize: 12 }}>
                        Approve delete
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </>
        )}
          </>
        )}
      </div>

      {dealModal && (
        <DealFormModal
          profile={profile}
          isAdmin={isFinanceAdmin(profile)}
          users={users}
          units={units}
          clients={clients}
          visibleSalesIds={visibleSalesIds}
          accounts={fin.accounts}
          getProjectInfo={getProjectInfo}
          initial={dealModal.initial}
          editing={dealModal.editing}
          onSave={saveDeal}
          onClose={() => setDealModal(null)}
        />
      )}

      {openUnit && (
        <div>
          <UnitModal
            unit={openUnit}
            projectInfo={getProjectInfo(openUnit)}
            canSeeOwner={canSeeOwner(openUnit)}
            handledBy={getHandledBy(openUnit)}
            onClose={() => setOpenUnit(null)}
            canDeleteDirectly={profile.role === "admin"}
            onDeleteDirectly={deleteUnitDirectly}
            onViewProfile={(id) => { setOpenUnit(null); setViewedUserId(id); }}
            assignableUsers={users.filter((u) => u.role !== "admin" && u.role !== "pending")}
            onReassign={reassignUnit}
            canEdit={profile.role === "admin" || openUnit.salesIds.includes(profile.id)}
            onEditRequest={(u) => { setOpenUnit(null); setEditingUnit(u); setTab("add"); }}
            onMarkSold={(u) => { setOpenUnit(null); setDealModal({ initial: { unitId: u.id } }); }}
            onRequestDelete={
              profile.role !== "admin" && openUnit.salesIds.some((id) => visibleSalesIds.includes(id))
                ? requestDelete
                : undefined
            }
            linkedClients={clientUnitLinks
              .filter((l) => l.unit_id === openUnit.id)
              .map((l) => clients.find((c) => c.id === l.client_id))
              .filter((c) => c && visibleSalesIds.includes(c.assignedTo))}
            onOpenClient={(c) => { setOpenUnit(null); setSection("clients"); setOpenClientId(c.id); }}
          />
          {openUnit.status === "active" && openUnit.salesIds.some((id) => visibleSalesIds.includes(id)) && (
            <div style={{ position: "fixed", bottom: 20, left: "50%", transform: "translateX(-50%)", zIndex: 60 }}>
              <button
                onClick={() => { setHoldTarget(openUnit); setOpenUnit(null); }}
                style={{ background: COLORS.danger, color: "#fff", border: "none", padding: "9px 18px", borderRadius: 8, cursor: "pointer", fontSize: 13 }}
              >
                Put on hold
              </button>
            </div>
          )}
        </div>
      )}

      <HoldModal unit={holdTarget} projectInfo={holdTarget ? getProjectInfo(holdTarget) : null} onConfirm={confirmHold} onCancel={() => setHoldTarget(null)} />
    </div>
  );
}
